`;var hC=`/* k.base\uFF1A\u6392\u7248\u9ED8\u8BA4\u503C\u3002\u8868\u9762\u4E0A\u4E0B\u6587\uFF08data-k-level\uFF09\u7684\u53D8\u91CF\u6620\u5C04\u7531 styles.ts \u6309\u5C42\u7EA7\u751F\u6210\u540E\u62FC\u5728\u8FD9\u91CC\u540E\u9762 */
